class MQBStandstillManager:
  ANNOUNCE_SPEED = 1.5      # m/s: start the ACC_07 stop announcement (HMS=1) below this while braking
  ANNOUNCE_MIN_SPEED = 0.5  # m/s: never announce slower than this, so it always ends before the wheels stop
  ANNOUNCE_FRAMES = 20      # 0.4 s at 50 Hz: the window in front of every fault-free hold (routes 332/333)
  RELEASE_SPEED = 2.6       # m/s (9.5 km/h, RJ ESP_OVERRIDE_SPEED): the stop episode ends once driving again
  UPHILL_ACCEL_FLOOR = 1.5

  def __init__(self, CCP):
    self._CCP = CCP
    self._prev_hold_confirmation = False
    self._announce_frames = 0
    self._hms4_latched = False

  def update(self, CS, long_active, accel, stopping, starting):
    esp_starting_override = None
    esp_stopping_override = None
    hms_active = long_active
    if CS.out.brakePressed:
      long_active = False
    v = CS.out.vEgo
    if long_active and accel > 0 and self._prev_hold_confirmation and (CS.out.standstill or v < 1.0):
      accel = min(max(accel, self.UPHILL_ACCEL_FLOOR), self._CCP.ACCEL_MAX)   # unchanged (needs bit 53)

    if not hms_active or v > self.RELEASE_SPEED:
      self._hms4_latched = False
      self._announce_frames = 0
    if not hms_active:
      stopping = starting = False   # HMS 0 at once on disengage (lcs lags a frame; ACC_06 bits are masked anyway)

    if hms_active:
      if self._hms4_latched:
        esp_starting_override, esp_stopping_override = True, False        # HMS 4, ACC_07 Anfahren, d 20.46
      elif self._announce_frames > 0 or (v < self.ANNOUNCE_SPEED and (accel < 0 or stopping)):
        if self._announce_frames >= self.ANNOUNCE_FRAMES or v < self.ANNOUNCE_MIN_SPEED:
          self._hms4_latched = True
          esp_starting_override, esp_stopping_override = True, False
        else:
          self._announce_frames += 1
          esp_starting_override, esp_stopping_override = False, True      # HMS 1, ACC_07 Anhalten, d 0.3

    self._prev_hold_confirmation = CS.esp_hold_confirmation
    return long_active, accel, stopping, starting, esp_starting_override, esp_stopping_override

This replaces the REQUESTING/HOLDING/RELEASING/4a/TIMEOUT machine. Those states depend on bit 53, which never sets on this car, and if bit 53 ever did set, HMS 4 still wins in mqbcan because acc07_starting is checked first. carcontroller.py only; no mqbcan, carstate or Params change. Prototype: /tmp/claude-0/-home-user-mk7-op-long-sng/48e1abac-3f14-57e3-a7c0-d6a536957af8/scratchpad/holdv2/design/candidates.py (CAND_A). Branch suggestion: hold_announce_early off t2_lead2_phantom_fix, a sibling of hold_tsk_owned, so the manager is the only difference.

